{
  "decisions": [
    {
      "entity_path": "config/archive_format",
      "change_type": "reject",
      "reasoning": "We rejected zstd archives because the downstream nightly archive importer cannot decode them. This constraint applies to nightly archives, not web images.",
      "constraint": "Nightly archives must be decodable by the downstream importer.",
      "stale_when": "Downstream archive importer adds tested zstd support."
    }
  ],
  "note": "This file is independent of any connected memory server."
}

{
  "status": "applied",
  "key": "thumbnail_format",
  "value": "webp",
  "rationale": "webp is the smallest supported format at 20 KB, compared to jpeg (30 KB) and png (80 KB). Current test evidence confirms that all target browsers and the deployed image pipeline pass webp compatibility tests, so there is no technical barrier to choosing it. No decision records constrain this choice."
}
